// Native names for the language picker (menu + Settings dialog). Keep in
// sync with dict — i18n-check.mjs enforces coverage.
export const LANG_NAMES = {
  en: 'English',
  fi: 'Suomi',
  sv: 'Svenska',
  de: 'Deutsch',
  fr: 'Français',
  es: 'Español',
  pt: 'Português',
  it: 'Italiano',
  nl: 'Nederlands',
  pl: 'Polski',
  ru: 'Русский',
  tr: 'Türkçe',
  zh: '中文（简体）',
  ja: '日本語',
  ko: '한국어',
};

let lang = 'en';

// detectLang picks the initial language: a stored choice first ('auto'
// follows the browser language), English when nothing is stored.
export function detectLang() {
  const saved = localStorage.getItem('s3b-lang');
  if (saved === 'auto') {
    const nav = (navigator.language || 'en').slice(0, 2).toLowerCase();
    return dict[nav] ? nav : 'en';
  }
  if (saved && dict[saved]) return saved;
  return 'en';
}

export function setLang(l) { if (dict[l]) lang = l; }
export function languages() { return Object.keys(dict); }

// t translates a key; {placeholder} tokens interpolate from params.
export function t(key, params = {}) {
  let s = dict[lang][key] ?? dict.en[key] ?? key;
  for (const [k, v] of Object.entries(params)) {
    s = s.replaceAll(`{${k}}`, String(v));
  }
  return s;
}

// has reports whether a key resolves in the active dictionary (falling
// back to en) — callers can tell "no such string" apart from t()'s
// raw-key fallback.
export function has(key) { return key in dict[lang] || key in dict.en; }
